using System.Collections.Generic;using SASZombieAssaultTD.Engine.Diagnostics;  using System.Collections.Generic;  namespace SASZombieAssaultTD.Engine.Rendering;  /// <summary> /// Data model for static UI and map layout definitions. /// Loaded from JSON configuration files. /// </summary> public sealed class StaticLayout {     public List<StaticImageEntry> Images { get; set; } = new(); }  /// <summary> /// Individual static image entry with position, size, and layer information. /// </summary> public sealed class StaticImageEntry {     public string Id { get; set; } = string.Empty;     public string Path { get; set; } = string.Empty;     public int X { get; set; }     public int Y { get; set; }     public int Width { get; set; }     public int Height { get; set; }     public int Layer { get; set; }     public bool Visible { get; set; } = true; }
